test('resolves only after every write has finished', async () => {
  const saved = new Map();
  const db = {
    async put(id, item) {
      await new Promise((r) => setTimeout(r, 10));
      saved.set(id, item);
    },
  };
  await saveAll([{ id: 1 }, { id: 2 }], db);
  assert.strictEqual(saved.size, 2);
});

test('rejects if a write fails', async () => {
  const db = {
    async put(id) {
      if (id === 2) throw new Error('boom');
    },
  };
  await assert.rejects(saveAll([{ id: 1 }, { id: 2 }], db), /boom/);
});

